/*!
 * Language: X++
 * Description: X++ for Microsoft Dynamics 365 Finance and Operations.
 * Website: https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/dev-ref/xpp-language-reference
 * Category: enterprise
 *
 * Highlight.js takes the canonical name from the filename, so this file is
 * xpp.js / xpp.min.js and registers "xpp". "axapta" and "x++" stay aliases:
 * the old Axapta name is superseded, and existing ```axapta fences still match.
 *
 * Load this file AFTER highlight.min.js. The bundle still ships a keyword-only
 * stub under the same name; this registration replaces that stub.
 *
 * Token classes used by js/highlightjs/styles/xpp.css:
 *   keyword, built_in, type, title.class, title.function, name,
 *   attribute, string, symbol, number, literal, comment, doctag, meta
 */
hljs.registerLanguage("xpp", function (hljs) {
  "use strict";

  function caseFold(word) {
    return word.replace(/[A-Za-z]/g, function (ch) {
      var lower = ch.toLowerCase();
      var upper = ch.toUpperCase();
      return lower === upper ? ch : "[" + lower + upper + "]";
    });
  }

  function caseFoldGroup(words) {
    var unique = [];
    var seen = Object.create(null);
    words.forEach(function (word) {
      if (!seen[word]) {
        seen[word] = true;
        unique.push(word);
      }
    });
    unique.sort(function (a, b) { return b.length - a.length; });
    return "(?:" + unique.map(caseFold).join("|") + ")";
  }

  function escapeRegExp(word) {
    return word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  var KEYWORDS = [
    "abstract", "as", "asc", "at", "avg", "break", "breakpoint", "by", "byref",
    "case", "catch", "changecompany", "class", "client", "const", "continue",
    "count", "crosscompany", "default", "delegate", "delete_from", "desc",
    "display", "div", "do", "edit", "else", "eventhandler", "eventHandler",
    "exists", "extends", "false", "final", "finally", "firstfast", "firstonly",
    "firstonly1", "firstonly10", "firstonly100", "firstonly1000", "flush",
    "for", "forceliterals", "forcenestedloop", "forceplaceholders",
    "forceselectorder", "forupdate", "from", "generateonly", "group", "hint",
    "if", "implements", "in", "index", "insert_recordset", "interface",
    "internal", "is", "join", "like", "maxof", "minof", "mod", "namespace",
    "new", "next", "nofetch", "notexists", "null", "optimisticlock", "order",
    "outer", "pessimisticlock", "print", "private", "protected", "public",
    "readonly", "repeatableread", "retry", "return", "reverse", "select",
    "server", "setting", "static", "sum", "super", "switch", "tablelock",
    "this", "throw", "true", "try", "ttsabort", "ttsbegin", "ttscommit",
    "unchecked", "update_recordset", "using", "validtimestate", "where", "while"
  ];

  var PRIMITIVES = [
    "anytype", "boolean", "byte", "char", "container", "date", "double",
    "enum", "guid", "int", "int64", "long", "real", "short", "str",
    "timeOfDay", "timeofday", "utcdatetime", "var", "void"
  ];

  var TYPES = [
    "Common", "common", "Args", "Object", "FormRun", "FormDataSource",
    "FormControl", "FormStringControl", "FormButtonControl", "FormDesign",
    "Query", "QueryRun", "QueryBuildDataSource", "QueryBuildRange",
    "QueryBuildFieldList", "SysQuery", "SysTableLookup", "SysDictTable",
    "SysDictField", "SysDictEnum", "SysDictClass", "SysDictMethod",
    "DictTable", "DictField", "DictEnum", "DictClass", "SysDaQueryObject",
    "SysDaSearchObject", "SysDaSearchStatement", "SysDaEqualsExpression",
    "SysDaFieldExpression", "SysDaValueExpression", "SysDaFirstOnlyHint",
    "SysDaInsertObject", "SysDaUpdateObject", "SysDaDeleteObject", "RunBase",
    "RunBaseBatch", "SysOperationServiceController", "SysOperationServiceBase",
    "SysOperationDataContractBase", "EventHandlerResult", "XppPrePostArgs",
    "Set", "SetEnumerator", "List", "ListEnumerator", "Map", "MapEnumerator",
    "Struct", "Array", "Types", "AccessRight", "NoYes", "NoYesId", "RecId",
    "RefRecId", "TableId", "RefTableId", "FieldId", "ClassId", "TableName",
    "FieldName", "ClassName", "IdentifierName", "Name", "Description", "Notes",
    "TransDate", "FromDate", "ToDate", "UtcDateTime", "CompanyId", "DataAreaId",
    "SelectableDataArea", "UserId", "Guid", "Exception", "ClrObject", "System",
    "DateTimeUtil", "Global", "appl", "infolog", "classFactory", "classfactory",
    "Dialog", "DialogField", "DialogBoxType", "FormEventArgs", "xFormRun",
    "MethodName", "Filename", "RecordInsertList", "URLUtility", "SecurityRights",
    "DocuRef", "DocuValue", "DocuRefSearch", "File", "Debug", "SysAttribute",
    "SysExtensionIAttribute", "SysExtensionAppClassFactory",
    "DataEntityRuntimeContext", "DataEntityDataSourceRuntimeContext",
    "EventArrivedEventArgs", "BusinessEventsEndpoint", "BusinessEventsEndpointBase",
    "IBusinessEventsEndpoint", "BusinessEventsEndpointPayloadContext", "SysBoxForm",
    "ItemId", "DocuTypeId", "AddRemove"
  ];

  // Compile-time intrinsics. Matched case-insensitively (classStr / classstr).
  var INTRINSICS = [
    "classStr", "tableStr", "fieldStr", "fieldPName", "methodStr",
    "staticMethodStr", "delegateStr", "staticDelegateStr", "formStr",
    "formControlStr", "formDataSourceStr", "formDataFieldStr", "formMethodStr",
    "menuItemDisplayStr", "menuItemActionStr", "menuItemOutputStr", "enumStr",
    "enumNum", "enumCnt", "enumLiteralStr", "literalStr", "identifierStr",
    "tableNum", "fieldNum", "classNum", "tableMethodStr", "tableStaticMethodStr",
    "tableFieldGroupStr", "configurationKeyStr",
    "configurationKeyNum", "licenseCodeStr", "securityKeyStr", "privilegeStr",
    "dutyStr", "roleStr", "tileStr", "queryStr", "queryDatasourceStr",
    "queryDataSourceStr", "reportStr", "ssrsReportStr", "resourceStr", "varStr",
    "extendedTypeStr", "extendedTypeNum", "measurementStr", "attributeStr",
    "workflowTypeStr", "workflowApprovalStr", "workflowTaskStr", "dataEntityViewStr",
    "dataEntityDataSourceStr", "compositeDataEntityViewStr", "serviceStr",
    "mapsTo", "tablePName", "dimensionHierarchyStr", "dimensionReferenceStr",
    "menuStr", "webMenuStr", "webActionItemStr", "webDisplayContentItemStr",
    "webOutputContentItemStr", "webSiteTempStr", "webManagedContentItemStr",
    "webUrlItemStr", "webWebPartStr", "webletItemStr", "workflowHierarchyProviderStr",
    "workflowParticipantProviderStr", "workflowQueueStr", "dataEntityActionStr"
  ];

  // Global / runtime functions (Global class and friends). Not method calls.
  var RUNTIME_FUNCTIONS = [
    "strFmt", "strFmtLB", "strScan", "strFind", "strNFind", "strDel", "strIns",
    "strLen", "strLwr", "strUpr", "strLRTrim", "strLTrim", "strRTrim",
    "strReplace", "strSplit", "str2Int", "str2Int64", "str2Num", "str2Date",
    "str2Datetime", "str2Guid", "str2Enum", "str2Con", "str2Time", "strAlpha",
    "strCmp", "strKeep", "strLine", "strPoke", "strPrompt", "strRem", "strRep",
    "strRFix", "strLFix", "subStr", "substr", "con2Str", "conDel", "conFind",
    "conIns", "conLen", "conNull", "conPeek", "conPoke", "conView", "any2Str",
    "any2Int", "any2Int64", "any2Real", "any2Date", "any2Enum", "any2Guid",
    "enum2Str", "enum2Int", "int2Str", "int642Str", "num2Str", "date2Str",
    "datetime2Str", "guid2Str", "time2Str", "date2Num", "today", "systemDateGet",
    "mkDate", "dayOfMth", "dayOfWk", "dayOfYr", "dayName", "wkOfYr", "mthOfYr",
    "year", "dateStartMth", "dateEndMth", "dateMthName", "timeNow", "info",
    "warning", "error", "checkFailed", "setPrefix", "getPrefix", "funcName",
    "prmIsDefault", "typeOf", "classIdGet", "className2Id", "classId2Name",
    "tableId2Name", "tableName2Id", "tableId2PName", "fieldName2Id",
    "fieldId2Name", "fieldId2PName", "indexName2Id", "indexId2Name", "newGuid",
    "curUserId", "curExt", "hasGUI", "sleep", "abs", "power", "round", "trunc",
    "frac", "exp", "exp10", "log10", "logN", "max", "min", "queryValue",
    "queryRange", "getCurrentThreadActivityId", "dimOf", "beep", "infologLine",
    "globalCache", "classNumGet"
  ];

  var KEYWORD_SET = {
    keyword: KEYWORDS,
    built_in: PRIMITIVES,
    type: TYPES
  };

  var IDENT = "[A-Za-z_][\\w]*";
  var QUALIFIED = "[A-Za-z_][\\w]*(?:\\.[A-Za-z_][\\w]*)*";
  var PASCAL = "[A-Z][A-Za-z0-9_]*";
  var PASCAL_QUALIFIED = PASCAL + "(?:\\." + PASCAL + ")+";

  var callExclusions = KEYWORDS.concat(PRIMITIVES).map(escapeRegExp).join("|");
  var intrinsicGroup = caseFoldGroup(INTRINSICS);
  var runtimeGroup = caseFoldGroup(RUNTIME_FUNCTIONS);

  var docTag = {
    className: "doctag",
    begin: /<\/?[A-Za-z_][\w.-]*/,
    end: /\/?>/,
    relevance: 0,
    contains: [
      {
        className: "attr",
        begin: /\b[A-Za-z_]\w*(?=\s*=)/,
        relevance: 0
      },
      hljs.QUOTE_STRING_MODE,
      hljs.APOS_STRING_MODE
    ]
  };

  var docComment = hljs.COMMENT("///", "$", {
    relevance: 0,
    contains: [docTag]
  });

  var labelString = function (quote) {
    return {
      className: "string",
      begin: quote === '"' ? /"(?=@)/ : /'(?=@)/,
      end: quote === '"' ? /"/ : /'/,
      illegal: /\n/,
      relevance: 0,
      contains: [
        {
          className: "symbol",
          begin: /@[A-Za-z_][A-Za-z0-9_]*(?::[A-Za-z_][A-Za-z0-9_]*)?/,
          relevance: 0
        },
        hljs.BACKSLASH_ESCAPE
      ]
    };
  };

  var strings = [
    labelString('"'),
    labelString("'"),
    hljs.inherit(hljs.QUOTE_STRING_MODE, { relevance: 0 }),
    hljs.inherit(hljs.APOS_STRING_MODE, { relevance: 0 })
  ];

  var comments = [
    docComment,
    hljs.C_LINE_COMMENT_MODE,
    hljs.C_BLOCK_COMMENT_MODE
  ];

  var basics = comments.concat(strings, [hljs.C_NUMBER_MODE]);

  function notPrecededByDot(match, response) {
    if (match.index > 0 && match.input[match.index - 1] === ".") {
      response.ignoreMatch();
    }
  }

  var qualifiedType = {
    className: "type",
    begin: new RegExp("\\b" + PASCAL_QUALIFIED + "(?:\\[\\])?"),
    relevance: 0,
    "on:begin": notPrecededByDot
  };

  var staticMethod = {
    match: [
      new RegExp("\\b" + QUALIFIED),
      /::/,
      new RegExp(IDENT + "(?=\\s*\\()")
    ],
    scope: {
      1: "type",
      3: "title.function"
    },
    relevance: 0
  };

  var staticLiteral = {
    match: [
      new RegExp("\\b" + QUALIFIED),
      /::/,
      new RegExp(IDENT)
    ],
    scope: {
      1: "type",
      3: "literal"
    },
    relevance: 0
  };

  var intrinsic = {
    className: "name",
    begin: new RegExp("\\b" + intrinsicGroup + "\\b(?=\\s*\\()"),
    relevance: 0
  };

  var runtimeFunction = {
    className: "name",
    begin: new RegExp("\\b" + runtimeGroup + "\\b(?=\\s*\\()"),
    relevance: 0
  };

  var argType = {
    className: "type",
    begin: new RegExp("\\b" + PASCAL + "(?=\\s*[,)\\]])"),
    relevance: 0,
    "on:begin": notPrecededByDot
  };

  var attributeName = {
    className: "title.class",
    // Only the attribute name: Foo or Foo.Bar immediately before "(" or "]".
    // A character class is avoided here — "\]" inside "[]" also matches ")".
    begin: new RegExp("\\b" + QUALIFIED + "(?=\\s*(?:\\(|\\]))"),
    relevance: 0,
    "on:begin": function (match, response) {
      var i = match.index - 1;
      while (i >= 0 && /[\s]/.test(match.input[i])) i--;
      if (i < 0 || match.input[i] !== "[") response.ignoreMatch();
    }
  };

  var attribute = {
    className: "attribute",
    begin: /\[(?=\s*[A-Za-z_][\w.]*(?:\s*\(|\s*\]))/,
    end: /\]/,
    relevance: 0,
    keywords: KEYWORD_SET,
    "on:begin": function (match, response) {
      if (match.index > 0 && /[\w.]/.test(match.input[match.index - 1])) {
        response.ignoreMatch();
      }
    },
    contains: basics.concat([
      intrinsic,
      runtimeFunction,
      staticMethod,
      staticLiteral,
      attributeName,
      qualifiedType,
      argType
    ])
  };

  var preprocessor = {
    className: "meta",
    begin: /^\s*#\s*[A-Za-z_]\w*/,
    end: /$/,
    relevance: 0,
    keywords: {
      keyword: "if else endif define undef localmacro endmacro macrolib macro ifnot defdec"
    },
    contains: comments.concat(strings, [
      hljs.C_NUMBER_MODE,
      {
        className: "type",
        begin: /\.\s*[A-Za-z_]\w*/,
        relevance: 0
      }
    ])
  };

  var macroRef = {
    className: "meta",
    begin: /#[A-Za-z_]\w*/,
    relevance: 0,
    "on:begin": function (match, response) {
      var before = match.input.slice(0, match.index);
      if (/(^|\n)\s*$/.test(before)) {
        response.ignoreMatch();
      }
    }
  };

  var usingImport = {
    begin: /\busing\b(?=\s+[A-Za-z_])/,
    end: /;/,
    relevance: 0,
    keywords: { keyword: "using" },
    contains: comments.concat([
      {
        className: "type",
        begin: new RegExp("\\b" + QUALIFIED),
        relevance: 0
      }
    ])
  };

  var classDecl = {
    match: [
      /\b(?:class|interface)\b/,
      /\s+/,
      new RegExp(IDENT)
    ],
    scope: {
      1: "keyword",
      3: "title.class"
    },
    relevance: 0
  };

  var extendsClause = {
    begin: /\b(?:extends|implements)\b/,
    end: /(?=[{;]|\r?\n)/,
    relevance: 0,
    keywords: KEYWORD_SET,
    contains: basics.concat([
      {
        className: "type",
        begin: new RegExp("\\b(?!(?:extends|implements)\\b)" + QUALIFIED),
        relevance: 0
      }
    ])
  };

  var newType = {
    match: [
      /\bnew\b/,
      /\s+/,
      new RegExp(QUALIFIED + "(?:\\[\\])?")
    ],
    scope: {
      1: "keyword",
      3: "type"
    },
    relevance: 0
  };

  var isAs = {
    match: [
      /\b(?:is|as)\b/,
      /\s+/,
      new RegExp(QUALIFIED + "(?:\\[\\])?")
    ],
    scope: {
      1: "keyword",
      3: "type"
    },
    relevance: 0
  };

  var methodDecl = {
    match: [
      new RegExp("\\b" + PASCAL),
      /\s+/,
      new RegExp(IDENT + "(?=\\s*\\()")
    ],
    scope: {
      1: "type",
      3: "title.function"
    },
    relevance: 0
  };

  var varDecl = {
    match: [
      new RegExp("\\b" + PASCAL),
      /\s+/,
      new RegExp(IDENT + "(?=\\s*[=;,)])")
    ],
    scope: {
      1: "type"
    },
    relevance: 0
  };

  var call = {
    className: "title.function",
    begin: new RegExp("\\b(?!(?:" + callExclusions + ")\\b)" + IDENT + "(?=\\s*\\()"),
    relevance: 0
  };

  return {
    name: "X++",
    aliases: ["axapta", "x++"],
    keywords: KEYWORD_SET,
    contains: [
      preprocessor,
      docComment,
      hljs.C_LINE_COMMENT_MODE,
      hljs.C_BLOCK_COMMENT_MODE,
      labelString('"'),
      labelString("'"),
      hljs.inherit(hljs.QUOTE_STRING_MODE, { relevance: 0 }),
      hljs.inherit(hljs.APOS_STRING_MODE, { relevance: 0 }),
      hljs.C_NUMBER_MODE,
      macroRef,
      attribute,
      usingImport,
      classDecl,
      extendsClause,
      newType,
      isAs,
      staticMethod,
      staticLiteral,
      intrinsic,
      runtimeFunction,
      qualifiedType,
      methodDecl,
      varDecl,
      argType,
      call
    ]
  };
});
